const decodedMessageSchemaResponseTransformer = (data: any) => {
    if (data.ext_in_msg_decoded) {
        if (data.ext_in_msg_decoded.wallet_v3) {
            data.ext_in_msg_decoded.wallet_v3.subwallet_id = BigInt(
                data.ext_in_msg_decoded.wallet_v3.subwallet_id.toString()
            );
            data.ext_in_msg_decoded.wallet_v3.valid_until = BigInt(
                data.ext_in_msg_decoded.wallet_v3.valid_until.toString()
            );
            data.ext_in_msg_decoded.wallet_v3.seqno = BigInt(
                data.ext_in_msg_decoded.wallet_v3.seqno.toString()
            );
        }
        if (data.ext_in_msg_decoded.wallet_v4) {
            data.ext_in_msg_decoded.wallet_v4.subwallet_id = BigInt(
                data.ext_in_msg_decoded.wallet_v4.subwallet_id.toString()
            );
            data.ext_in_msg_decoded.wallet_v4.valid_until = BigInt(
                data.ext_in_msg_decoded.wallet_v4.valid_until.toString()
            );
            data.ext_in_msg_decoded.wallet_v4.seqno = BigInt(
                data.ext_in_msg_decoded.wallet_v4.seqno.toString()
            );
        }
        if (data.ext_in_msg_decoded.wallet_v5) {
            data.ext_in_msg_decoded.wallet_v5.valid_until = BigInt(
                data.ext_in_msg_decoded.wallet_v5.valid_until.toString()
            );
        }
        if (data.ext_in_msg_decoded.wallet_highload_v2) {
            data.ext_in_msg_decoded.wallet_highload_v2.subwallet_id = BigInt(
                data.ext_in_msg_decoded.wallet_highload_v2.subwallet_id.toString()
            );
        }
    }
    return data;
};

